import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"CPU 控制器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ch014.md","filePath":"zh/ch014.md"}`),a={name:`zh/ch014.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cpu-控制器" tabindex="-1">CPU 控制器 <a class="header-anchor" href="#cpu-控制器" aria-label="Permalink to “CPU 控制器”">​</a></h1><p>CPU 利用率是实施 cgroup2 架构能够带来重大资源控制改进的另一个领域。本节介绍使用 cgroup2 开始控制 CPU 资源所需的概念和策略，并包含一个案例研究，展示当今生产环境中如何使用 CPU 控制器来控制和监控 Facebook 数据中心的 CPU 使用情况。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>启用后，CPU 控制器会调节 CPU 周期的分配，并为其子 cgroup 强制执行 CPU 限制。它为普通调度策略实现了权重模型和绝对带宽限制模型，并为实时调度策略实现了绝对带宽分配模型。</p><div class="warning custom-block"><p>警告：只有当所有实时进程都位于根 cgroup 中时，才能启用 CPU 控制器，因为 cgroup2 尚不支持对实时进程的控制。</p><p>请注意，系统管理软件可能在系统启动过程中已将实时进程放入非根 cgroup，因此在启用 CPU 控制器之前，可能需要将这些进程移回根 cgroup。</p></div><h2 id="接口文件" tabindex="-1">接口文件 <a class="header-anchor" href="#接口文件" aria-label="Permalink to “接口文件”">​</a></h2><p>与其他 cgroup2 控制器一样，CPU 控制器在启用时会在其子 cgroup 中创建一组对应的接口文件。你通过修改这些接口文件来调整 CPU 资源的分配，通常是在 Chef recipe 或其他部署工具的配置中进行。其他接口文件允许你查询和监控 cgroup 的统计信息。</p><p>请务必参阅权威的 <a href="https://git.kernel.org/pub/scm/linux/kernel/git/tj/cgroup.git/tree/Documentation/admin-guide/cgroup-v2.rst" target="_blank" rel="noreferrer">cgroup v2 参考文档</a>以获取有关 CPU 控制器文件的更多细节</p><table tabindex="0"><thead><tr><th style="text-align:left;">文件</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cpu.stat</code></td><td style="text-align:left;">无论控制器是否启用，此文件都存在。它始终报告以下三项统计信息： <br> <br> <ul><li><code>usage_usec</code></li><li><code>user_usec</code></li><li><code>system_usec</code></li></ul> <br> <br> 控制器启用时，它还会报告以下三项: <br> <br> <ul><li><code>nr_periods</code></li><li><code>nr_throttled</code></li><li><code>throttled_usec</code></li></ul></td></tr><tr><td style="text-align:left;"><code>cpu.weight</code></td><td style="text-align:left;">存在于非根 cgroup 上的单值文件，用于设置比例带宽限制。默认值为 100。权重范围为 [1, 10000]。</td></tr><tr><td style="text-align:left;"><code>cpu.weight.nice</code></td><td style="text-align:left;">这是 cpu.weight 的替代接口，允许使用与 nice 相同的值来读取和设置权重。 <br> <br> 默认值为 0。nice 值范围为 [-20, 19]。由于 nice 值的范围更小且粒度更粗，读取值是当前权重的最近似值。</td></tr><tr><td style="text-align:left;"><code>cpu.max</code></td><td style="text-align:left;">最大带宽限制。格式为：<code>$MAX $PERIOD</code>，表示该组在每个 <code>$PERIOD</code> 持续时间内最多可消耗 <code>$MAX</code>。 <code>$MAX</code> 使用<code>max</code>表示无限制。如果只写入一个数字，则更新 <code>$MAX</code> 。默认值为 <code>max 100000</code> 。</td></tr><tr><td style="text-align:left;"><code>cpu.pressure</code></td><td style="text-align:left;">CPU 压力的度量。请参阅下文讨论。</td></tr></tbody></table><h2 id="使用-psi-测量-cpu-压力" tabindex="-1">使用 PSI 测量 CPU 压力 <a class="header-anchor" href="#使用-psi-测量-cpu-压力" aria-label="Permalink to “使用 PSI 测量 CPU 压力”">​</a></h2><p>CPU 控制器在 <code>cpu.pressure</code> 文件中跟踪压力停滞信息（PSI）。</p><p>它显示一项统计信息：<code>some</code>，即一个或多个任务等待 CPU 可用的实际时间百分比。</p><p><code>some avg10=2.04 avg60=0.75 avg300=0.40 total=157656722</code></p><p>前三个数字分别是最近约 10 秒、1 分钟和 5 分钟的滑动平均值。</p><p>total 值给出以微秒为单位的绝对停滞时间。这允许检测可能太短而无法影响滑动平均值的延迟尖峰。</p><p>有关 PSI 指标的更多细节，请参阅 <a href="https://facebookmicrosites.github.io/psi/" target="_blank" rel="noreferrer">PSI 文档</a>。</p><h2 id="案例研究-优化-facebook-laser-服务的-cpu-利用率" tabindex="-1">案例研究：优化 Facebook Laser 服务的 CPU 利用率 <a class="header-anchor" href="#案例研究-优化-facebook-laser-服务的-cpu-利用率" aria-label="Permalink to “案例研究：优化 Facebook Laser 服务的 CPU 利用率”">​</a></h2><p>为了制定提高 CPU 利用率的策略，Facebook 的资源控制团队与组织内各基础设施团队合作。本节介绍一个使用 cgroup2 CPU 控制器的案例研究，该研究为名为 Laser 的内部数据聚合服务实现了对 CPU 资源的更好控制。</p><h3 id="概述-1" tabindex="-1">概述 <a class="header-anchor" href="#概述-1" aria-label="Permalink to “概述”">​</a></h3><p>Laser 是一项数据发布服务，它将高带宽数据流处理为可索引的数据库。这些数据流在很大程度上由名为 Scribe 的服务的日志数据组成；Scribe 是一种分布式消息系统，用于以低延迟收集和聚合高容量消息数据，在 Facebook 的生产环境中广泛使用。</p><p>Laser 读取、解析、索引和存储 Scribe 数据，并将其提供给 Facebook 内的各个团队。不同领域有数百个独立的 Laser 实例，分布在一个主机池上，每台主机上有数十个实例。每个实例读取其各自 Scribe 管道中的数据，并将其送入匹配的 Laser 索引。每个 Laser 实例都存在于自己的容器中，使用 Facebook 的内部容器化解决方案 Tupperware，每个 Laser 实例对应一个 Tupperware 作业。</p><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h3><p>在实施 cgroup2 之前，Laser 团队经常遇到性能问题，原因是某个 Laser 实例占用了大部分 CPU，使其他线程得不到资源。</p><p>另一个问题是，当池中的主机变忙时，Laser 实例会被迁移到其他主机：由于需要处理新机器上的积压和其他事项，CPU 使用率通常会进一步飙升，占用主机的全部周期，导致更多 CPU 控制问题。</p><p>此外，由于 Laser 实例是共置的，Laser 团队需要一种方法来保证每个实例的 CPU 资源量，同时隔离任何吵闹的邻居。</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to “解决方案”">​</a></h3><p>每个 Laser 实例都使用 Tupperware，每个 Tupperware 实例都启用了 CPU 控制器。Laser 使用每个 Tupperware 实例中的 CPU 控制器来更公平地分配 CPU 资源，并保证每个 Laser 实例的 CPU 资源量。</p><p>在此案例中，CPU 控制器使用比例控制（而非最大带宽限制）：因此，每个实例的 CPU 设置都在 cpu.weight 中设置。</p><p>下图展示了根据 Tupperware 作业 cpu.weight 中的设置分配 CPU 的结果：蓝线显示的 Laser 作业出现延迟尖峰，而其他作业的 CPU 得到保证，其延迟保持较低水平。</p><p><img src="/p002/ch01/006.png" alt="" width="1512" height="1494"></p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};